templates.source:
classDiagram
  class Customer {
    +name: string
    +email: string
  }
  class Order {
    +placed: date
    +total(): number
  }
  class Product {
    +title: string
    +price: number
  }
  Customer "1" --> "*" Order : places
  Order "*" --> "*" Product : contains

erDiagram
  CUSTOMER {
    int id PK
    string name
    string email
  }
  ORDER {
    int id PK
    date placed
  }
  PRODUCT {
    int id PK
    string title
    float price
  }
  CUSTOMER ||--o{ ORDER : places
  ORDER }|--|{ PRODUCT : contains
